def find_divisors(n: int) -> Set[int]:
    """
    Find all divisors of a number.
    - O(sqrt(n)) time-complexity
    - O(n) space-complexity
    """
    divisors = {1, n}
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return divisors
